import re
terms = ['prelude','CompilerLibrary','compiler library','library route','one library','fork','reserved','ladder','climb','arrays','Array','nat ','twice','re-implement','reimplement','port ','two libraries','both worlds','duplicate']
for tag in ('archived','live'):
    for fn,label in (('assistant-text.md','A'),('user-messages.md','U')):
        txt=open(f'{tag}/{fn}',encoding='utf-8').read()
        if label=='U':
            txt='## A.'+txt.split('## A.')[1].split('\n## B.')[0]
        for m in re.finditer(r'### \d+\. (\S+)\s+\(([^)]*)\)\n(.*?)(?=\n### |\Z)', txt, re.S):
            ts,meta,body=m.group(1),m.group(2),m.group(3)
            hits=[t.strip() for t in terms if t.lower() in body.lower()]
            if hits:
                print(f'{tag} {label} {ts} [{",".join(hits)}] {len(body)}')
EOF
